{
  "name": "magpie-gemini-media-tools",
  "version": "0.1.1",
  "description": "Gemini media tools MCP hook plugin for Magpie (image generation, editing, media analysis, TTS)",
  "type": "module",
  "main": "./index.mjs",
  "files": [
    "index.mjs",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "magpie",
    "magpie-plugin",
    "opencode",
    "opencode-plugin",
    "mcp",
    "gemini",
    "media-tools",
    "image-generation",
    "tts"
  ],
  "author": "qq136692547-cmyk",
  "homepage": "https://github.com/qq136692547-cmyk/magpie-gemini-media-tools#readme",
  "bugs": {
    "url": "https://github.com/qq136692547-cmyk/magpie-gemini-media-tools/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/qq136692547-cmyk/magpie-gemini-media-tools.git"
  },
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test index.test.mjs"
