    "maxConcurrency": 4,
    "options": {
      "apiKey": "AIza...",
      "imageModel": "gemini-nano-banana-2.1",
      "mediaModel": "gemini-3.8-flash",
      "ttsModel": "gemini-3.8-flash-tts",
      "restrictToWorkspace": false
    },
    "summary": {
      "en": "Gemini media tools: image generation, image editing, media analysis, and text-to-speech.",
      "zh": "Gemini 媒体工具集：支持生图、改图、媒体分析和文字转语音。"
    }
  }
